namespace SMDWin.Views
{
    /// <summary>
    /// The pages moved into views/Pages (UserControls). The code in MainWindow.*.cs uses them as before: every named element
    /// of a page is a property here, and FindName searches the pages too.
    /// While a page is still loading (XAML events at start-up), its properties return null — exactly like the old generated
    /// fields, which the code already checks with "!= null" / "?.".
    /// </summary>
    public partial class MainWindow
    {
        /// <summary>Finds an element by name in the window and then in the separate pages.</summary>
        public new object? FindName(string name)
        {
            var found = base.FindName(name);
            if (found != null) return found;
            foreach (var page in new System.Windows.FrameworkElement?[] { PageDashboard, PageTempStress, PageStorage, PageRam, PageNetwork, PageSettings, PagePower })
                if (page?.FindName(name) is { } inPage) return inPage;
            return null;
        }

